const VISUAL_HISTORY_REBUILD_CODE_BLOCK_END = 23;
const VISUAL_HISTORY_REBUILD_PARAGRAPH_START = 1;
const VISUAL_HISTORY_REBUILD_PARAGRAPH_END = 4;
